					"contenuto": "class_name TestShake
extends RefCounted


func test_shake_command(interpreter: StoryInterpreter) -> bool:
	if not interpreter or not interpreter.character_stage:
		return false

	var start_pos: Vector2 = interpreter.character_stage.position
	var start_time := Time.get_ticks_msec()

	await interpreter.execute_command({\"type\": \"shake\", \"duration\": 0.2, \"strength\": 8.0})

	var elapsed := Time.get_ticks_msec() - start_time
	if elapsed < 150 or elapsed > 450:
		return false

	if interpreter.character_stage.position.distance_to(start_pos) > 0.5:
		return false

	return true
